pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, uint56 _changeFee, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves) public {
        // Keep fuzzed domain wide: feeRate can be any uint16, but we don't bound it
        // Setup: prank a caller and call initialize with fuzzed feeRate
        address caller = address(0x1234);
        vm.prank(caller);
        try c.initialize(
            address(0),
            address(0xDead),
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            // If initialized succeeded, feeRate must be <= 5000
            assertTrue(c.feeRate() <= 5_000);
        } catch {
            // If initialize reverted (e.g. AlreadyInitialized), that's fine
            vm.stopPrank();
            // Re-deploy or skip; but we can just send a fresh c for each fuzz run
            // Actually, each fuzz run gets a fresh c because each call is independent in Foundry fuzz.
            // AlreadyInitialized will happen on second calls? No, Setup runs once, but fuzz runs are independent with fresh state.
            // Wait: Foundry fuzz tests run setUp once, then run test multiple times with different inputs on a clean copy of the state.
            // So each fuzz run has a clean c, initialized = false. So initialize should succeed. No AlreadyInitialized.
            // So the catch block won't be hit unless initialization reverts for another reason (e.g., feeRate too high in reference).
            // We can just leave empty.
        }
    }
}

