pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Bound to a range that includes values above 5_000 so the fuzzer can trigger the bug.
        _feeRate = _feeRate % 10_001;
        // Admissible domain: feeRate must not revert during initialize.
        // We need a successful initialization to test the post-condition on stored feeRate.
        bool ok;
        try c.initialize(
            address(0),
            address(0),
            1,
            1,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            uint16 storedFeeRate = c.feeRate();
            assertTrue(storedFeeRate <= 5_000, "stored feeRate must not exceed 5_000");
        } else {
            // Reverted, no stored feeRate to check.
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Restrict _feeRate to the valid domain (<= 5000) to avoid the built-in FeeRateTooHigh revert,
        // which would prevent observing the actual stored value.
        vm.assume(_feeRate <= 5000);

        // Attempt to initialize the pool. If it reverts for any reason (e.g., AlreadyInitialized),
        // the test does not assert on stored state and passes vacuously (the property holds trivially).
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            // Initialization succeeded: the stored feeRate must equal the _feeRate argument that was passed.
            assertEq(c.feeRate(), _feeRate);
        } catch {
            // Initialization reverted: no assertion needed.
        }
    }
}
